/**
 * Pre-rendered head-turn + blink frames for <LivePortrait />.
 * Generated by scripts/live-portrait (see its README).
 * Files: {dir}avif/p{pitch}y{yaw}e{eye}.avif (HD, primary) and {dir}webp/… (80% size, fallback),
 * plus {dir}base.avif / base.webp — the body with the frame rectangle cut out.
 */
export const livePortrait = {
  dir: '/assets/live/',
  width: 1200,
  height: 1339,
  /** where every frame sits on the base: [x, y, w, h] (frames are scaled to fit) */
  rect: [142, 6, 799, 873] as [number, number, number, number],
  /** head yaw per frame column, degrees (negative = turned to the viewer's right) */
  yaws: [-18.0, -15.75, -13.5, -11.25, -9.0, -6.75, -4.5, -2.25, 0.0, 2.25, 4.5, 6.75, 9.0, 11.25, 13.5, 15.75, 18.0],
  /** head pitch per frame row, degrees (negative = looking up) */
  pitches: [-7, -3.5, 0, 3.5, 7],
  /** eye states: open, closed */
  eyes: [0, -1.0],
  /** maps cursor direction onto the frame grid */
  yawSign: 1,
  pitchSign: 1,
};
